// Street lamps repeat along the boulevard.
const lamps=[];function makeLamp(x,z){const g=group(scene,x,0,z);cylinder(g,.08,.12,3,mat(0x454954),0,1.5,0);box(g,.8,.09,.11,mat(0x454954),x>0?-.3:.3,3,0);const light=box(g,.38,.1,.25,mat(0xffe8a4),x>0?-.62:.62,2.95,0);light.material.emissive=new THREE.Color(0x8c5721);return g}for(let s of [-1,1])for(let i=0;i<5;i++)lamps.push({mesh:makeLamp(s*6.6,-i*29-15),side:s});

// Hero and the very persistent officer.
function makeRunner(isCop=false){const root=group(scene);const rig=group(root);const shirt=isCop?materials.blue:materials.hoodie,pants=isCop?materials.copBlue:materials.pants;
 box(rig,.68,.78,.38,shirt,0,1.25,0);box(rig,.48,.12,.4,isCop?materials.copBlue:materials.hoodieShade,0,.9,0);
 sphere(rig,.26,materials.skin,0,1.91,0,1,1.04,.94);sphere(rig,.28,isCop?materials.blue:materials.hair,0,2.12,-.015,1,.48,1.04);
 if(isCop){box(rig,.5,.09,.48,materials.blue,0,2.14,0);box(rig,.31,.06,.37,materials.gold,0,2.19,0);box(rig,.16,.12,.08,materials.gold,0,1.48,.21)}else{const hood=sphere(rig,.25,materials.hoodieShade,0,1.66,.19,.95,.9,.68);box(rig,.39,.45,.12,materials.dark,0,1.24,.25);box(rig,.16,.2,.08,materials.spray,0,1.26,.34)}
 const arms=[],legs=[];for(const s of [-1,1]){const a=group(rig,s*.43,1.53,0);cylinder(a,.105,.085,.65,shirt,0,-.27,0,10);sphere(a,.105,materials.skin,0,-.61,0);arms.push(a);const l=group(rig,s*.2,.87,0);cylinder(l,.14,.12,.68,pants,0,-.3,0,10);box(l,.18,.16,.38,materials.shoe,0,-.68,-.08);legs.push(l)}return{root,rig,arms,legs}}
const player=makeRunner(false);player.root.position.set(0,0,.2);const cop=makeRunner(true);cop.root.position.set(0,0,4.35);cop.root.scale.setScalar(.9);
const lanes=[-2.75,0,2.75];let lane=1;const playerShadow=new THREE.Mesh(new THREE.CircleGeometry(.65,20),new THREE.MeshBasicMaterial({color:0x151925,transparent:true,opacity:.32}));playerShadow.rotation.x=-Math.PI/2;playerShadow.position.set(0,.015,.25);scene.add(playerShadow);

const active=[];const paint=[];let worldSpeed=0;let spawnClock=0;let distance=0;let coins=0;let score=0;let running=false;let over=false;let jumpTimer=0;let slideTimer=0;let flashTimer=0;let best=Number(localStorage.getItem('sprayRunBest')||0);document.querySelector('#best').textContent=String(best).padStart(6,'0');
function makeCar(police=false){const g=group(scene);const body=box(g,1.65,.58,2.65,police?materials.blue:materials.red,0,.67,0);body.scale.set(1,1,.94);box(g,1.38,.55,1.3,materials.glass,0,1.12,-.12);box(g,1.45,.12,.5,police?materials.white:materials.red,0,.84,-.83);box(g,.4,.14,.18,materials.white,-.48,.69,-1.34);box(g,.4,.14,.18,materials.white,.48,.69,-1.34);box(g,.34,.12,.14,materials.red,-.48,.7,1.33);box(g,.34,.12,.14,materials.red,.48,.7,1.33);if(police){box(g,.7,.13,.28,materials.red,-.26,1.47,-.12);box(g,.7,.13,.28,materials.blue,.26,1.47,-.12)}for(const x of [-.89,.89])for(const z of [-.8,.83]){const w=cylinder(g,.29,.29,.15,materials.dark,x,.38,z,14);w.rotation.z=Math.PI/2;cylinder(g,.14,.14,.16,mat(0xbfc6bf),x,.38,z,12).rotation.z=Math.PI/2}return g}
function makeBarrier(){const g=group(scene);box(g,1.95,.58,.34,materials.white,0,.66,0);for(let x=-.78;x<.9;x+=.52){const stripe=box(g,.28,.63,.36,materials.red,x,.66,0);stripe.rotation.z=-.42}for(const x of [-.7,.7])box(g,.16,.48,.2,materials.dark,x,.22,0);return g}
function makeCrate(){const g=group(scene);box(g,1.18,1.1,1.05,materials.concrete,0,.58,0);box(g,1.2,.11,1.08,materials.brick,0,1.13,0);for(const x of [-.32,.32])box(g,.11,.86,1.08,materials.brick,x,.58,.01);return g}
function makeCan(){const g=group(scene);cylinder(g,.22,.22,.56,materials.spray,0,.31,0,16);cylinder(g,.1,.1,.08,materials.dark,0,.63,0,12);box(g,.2,.15,.02,materials.white,0,.3,.2);const ring=new THREE.Mesh(new THREE.TorusGeometry(.24,.025,7,18),materials.gold);ring.position.y=.35;g.add(ring);return g}
function addEntity(type,laneIndex,z){const x=lanes[laneIndex];let mesh;if(type==='barrier')mesh=makeBarrier();else if(type==='crate')mesh=makeCrate();else if(type==='car')mesh=makeCar(Math.random()<.25);else mesh=makeCan();mesh.position.x=x;mesh.position.z=z;scene.add(mesh);active.push({mesh,type,lane:laneIndex,z,passed:false,phase:Math.random()*6.28})}
function spawnWave(){const difficulty=Math.min(1,distance/1200),roll=Math.random(),row=Math.random()<.36+ difficulty*.12;let blocked=new Set();if(roll<.34){const l=Math.floor(Math.random()*3);const type=Math.random()<.52?'barrier':'crate';addEntity(type,l,-83);blocked.add(l)}else if(roll<.64){const l=Math.floor(Math.random()*3);addEntity('car',l,-83);blocked.add(l)}else if(roll<.83){const safe=Math.floor(Math.random()*3);for(let i=0;i<3;i++)if(i!==safe){addEntity(Math.random()<.5?'barrier':'car',i,-83);blocked.add(i)}}if(row){const pick=Math.floor(Math.random()*3);for(let j=0;j<5;j++)if(!blocked.has(pick)||j%2===0){const e=makeCan();e.position.set(lanes[pick],.4+(j%2)*.12,-77-j*3.1);scene.add(e);active.push({mesh:e,type:'can',lane:pick,z:e.position.z,passed:false,phase:j})}}}

