function spawnWave(){const difficulty=Math.min(1,distance/1200),roll=Math.random(),row=Math.random()<.36+difficulty*.12;let blocked=new Set();if(roll<.34){const l=Math.floor(Math.random()*3);const type=Math.random()<.52?'barrier':'crate';addEntity(type,l,-83);blocked.add(l)}else if(roll<.64){const l=Math.floor(Math.random()*3);addEntity('car',l,-83);blocked.add(l)}else if(roll<.83){const safe=Math.floor(Math.random()*3);for(let i=0;i<3;i++)if(i!==safe){addEntity(Math.random()<.5?'barrier':'car',i,-83);blocked.add(i)}}if(row){const pick=Math.floor(Math.random()*3);for(let j=0;j<5;j++)if(!blocked.has(pick)||j%2===0){const e=makeCan();e.position.set(lanes[pick],.4+(j%2)*.12,-77-j*3.1);scene.add(e);active.push({mesh:e,type:'can',lane:pick,z:e.position.z,passed:false,phase:j})}}}

const hud=document.querySelector('#hud'),start=document.querySelector('#start'),gameover=document.querySelector('#gameover'),toast=document.querySelector('#toast');
function startGame(){for(const e of active)scene.remove(e.mesh);active.length=0;lane=1;player.root.position.set(0,0,.2);player.root.scale.set(1,1,1);cop.root.position.set(0,0,4.35);distance=0;coins=0;score=0;worldSpeed=17;spawnClock=1.05;jumpTimer=slideTimer=0;running=true;over=false;hud.style.display='block';start.style.display='none';gameover.style.display='none';document.querySelector('#sound').style.display='grid';document.querySelector('#score').textContent='000000';document.querySelector('#coins').textContent='00'}
function endGame(){if(!running)return;running=false;over=true;hud.style.display='none';gameover.style.display='grid';document.querySelector('#final-score').textContent=String(score).padStart(6,'0');document.querySelector('#final-coins').textContent=String(coins).padStart(2,'0');best=Math.max(best,score);localStorage.setItem('sprayRunBest',best);document.querySelector('#best').textContent=String(best).padStart(6,'0')}
function act(action){if(!running)return;if(action==='left')lane=Math.max(0,lane-1);if(action==='right')lane=Math.min(2,lane+1);if(action==='jump'&&jumpTimer<=0&&slideTimer<=0)jumpTimer=.72;if(action==='slide'&&jumpTimer<=0)slideTimer=.72}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup','arrowdown',' ','a','d','w','s'].includes(k))e.preventDefault();if(k==='arrowleft'||k==='a')act('left');if(k==='arrowright'||k==='d')act('right');if(k==='arrowup'||k==='w'||k===' ')act('jump');if(k==='arrowdown'||k==='s')act('slide');if((k==='enter'||k===' ')&&!running&&(!over||gameover.style.display!=='none')){if(start.style.display!=='none'||over)startGame()}});
document.querySelectorAll('[data-action]').forEach(btn=>{btn.addEventListener('pointerdown',e=>{e.preventDefault();act(btn.dataset.action)})});document.querySelector('#play').addEventListener('click',startGame);document.querySelector('#again').addEventListener('click',startGame);
let last=performance.now(),toastTimeout=0;
function updateWorld(dt){const speed=worldSpeed*dt;distance+=speed;worldSpeed=Math.min(30,17+distance*.0023);for(const seg of roadSegments){seg.position.z+=speed;if(seg.position.z>11)seg.position.z-=140}for(const b of buildings){b.mesh.position.z+=speed;if(b.mesh.position.z>15){b.mesh.position.z-=135;b.seed++;}}
 for(const p of props){p.mesh.position.z+=speed;if(p.mesh.position.z>14)p.mesh.position.z-=136}for(const l of lamps){l.mesh.position.z+=speed;if(l.mesh.position.z>17)l.mesh.position.z-=145}
 spawnClock-=dt;if(spawnClock<=0){spawnWave();spawnClock=Math.max(1.05,1.52-distance*.00018)+(Math.random()*.38)}
 if(jumpTimer>0)jumpTimer=Math.max(0,jumpTimer-dt);if(slideTimer>0)slideTimer=Math.max(0,slideTimer-dt);
 const targetX=lanes[lane];player.root.position.x+=(targetX-player.root.position.x)*Math.min(1,dt*11);player.rig.position.y=jumpTimer>0?Math.sin((.72-jumpTimer)/.72*Math.PI)*1.58:0;player.root.scale.y=slideTimer>0?.58:1;player.root.position.y=slideTimer>0?0:0;
 player.legs.forEach((leg,i)=>{const run=running?Math.sin(performance.now()*.012+i*Math.PI)*.52:0;leg.rotation.x=jumpTimer>0?-.3:run;player.arms[i].rotation.x=jumpTimer>0?(i===0?-.9:.9):Math.sin(performance.now()*.012+i*Math.PI+Math.PI)*.48});
 cop.root.position.x+=(targetX-cop.root.position.x)*Math.min(1,dt*3);cop.legs.forEach((leg,i)=>leg.rotation.x=Math.sin(performance.now()*.012+i*Math.PI)*.43);cop.arms.forEach((arm,i)=>arm.rotation.x=Math.sin(performance.now()*.012+i*Math.PI+Math.PI)*.5);
 playerShadow.position.x=player.root.position.x;playerShadow.material.opacity=jumpTimer>0?.16:.3;
 for(let i=active.length-1;i>=0;i--){const e=active[i];e.mesh.position.z+=speed;e.z=e.mesh.position.z;if(e.type==='can'){e.mesh.rotation.y+=dt*2.7;e.mesh.position.y=.38+Math.sin(performance.now()*.004+e.phase)*.12}
  if(e.type==='can'&&e.lane===lane&&Math.abs(e.z-.2)<1.25){coins++;score+=50;scene.remove(e.mesh);active.splice(i,1);document.querySelector('#coins').textContent=String(coins).padStart(2,'0');toast.style.opacity='1';clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>toast.style.opacity='0',700);continue}
  if(e.type!=='can'&&e.lane===lane&&Math.abs(e.z-.2)<1.16){const jumped=jumpTimer>.2&&e.type==='barrier';if(!jumped){cop.root.position.z=3.15;endGame();return}else{score+=100;cop.root.position.z=4.8}}
  if(e.z>10){scene.remove(e.mesh);active.splice(i,1)}
 }
 score=Math.floor(distance*1.35)+coins*50;document.querySelector('#score').textContent=String(score).padStart(6,'0');document.querySelector('#meter').style.width=`${Math.min(100,(distance%450)/4.5)}%`;
}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.04,(now-last)/1000);last=now;if(running)updateWorld(dt);else{player.legs.forEach((l,i)=>l.rotation.x=Math.sin(now*.002+i*Math.PI)*.08);player.arms.forEach((a,i)=>a.rotation.x=Math.sin(now*.002+i*Math.PI+Math.PI)*.08)}
 player.root.position.x+=(lanes[lane]-player.root.position.x)*Math.min(1,dt*4);camera.position.x+=(player.root.position.x*.23-camera.position.x)*dt*2;camera.lookAt(player.root.position.x*.12,1.1,-7);renderer.render(scene,camera)}requestAnimationFrame(animate);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight)});
</script>
</body></html>

